<section class="account-section"><div class="container"><?php require __DIR__ . '/_nav.php'; ?><div class="row g-4"><div class="col-lg-5"><div id="new-address" class="easy-form-card sticky-card"><h2 class="h4 mb-3">Add an address</h2><form method="post" action="<?= e(url('controller/router.php?action=customer.address.create')) ?>" novalidate><?= csrf_field() ?><div class="mb-3"><label for="address-label">Label</label><input class="form-control" id="address-label" name="label" placeholder="Home, Office or Client" value="<?= form_value($state, 'label') ?>" required><?= form_error($state, 'label') ?></div><div class="mb-3"><label for="address-recipient">Recipient name</label><input class="form-control" id="address-recipient" name="recipient_name" value="<?= form_value($state, 'recipient_name', (string) (CustomerAuth::user()['name'] ?? '')) ?>" required><?= form_error($state, 'recipient_name') ?></div><div class="mb-3"><label for="address-phone">Phone</label><input class="form-control" id="address-phone" name="phone" value="<?= form_value($state, 'phone', (string) (CustomerAuth::user()['phone'] ?? '')) ?>" required><?= form_error($state, 'phone') ?></div><div class="mb-3"><label for="address-line">Street address</label><input class="form-control" id="address-line" name="address_line" value="<?= form_value($state, 'address_line') ?>" required><?= form_error($state, 'address_line') ?></div><div class="row g-3"><div class="col-6"><label for="address-city">City</label><input class="form-control" id="address-city" name="city" value="<?= form_value($state, 'city') ?>" required><?= form_error($state, 'city') ?></div><div class="col-6"><label for="address-state">State / region</label><input class="form-control" id="address-state" name="state_name" value="<?= form_value($state, 'state_name') ?>" required><?= form_error($state, 'state_name') ?></div></div><div class="mt-3 mb-3"><label for="address-country">Country code</label><input class="form-control text-uppercase" id="address-country" name="country_code" maxlength="2" value="<?= form_value($state, 'country_code', 'NG') ?>" required><?= form_error($state, 'country_code') ?></div><div class="mb-3"><label for="address-directions">Landmark / directions</label><textarea class="form-control" id="address-directions" name="directions"><?= form_value($state, 'directions') ?></textarea></div><div class="form-check mb-4"><input class="form-check-input" type="checkbox" id="address-default" name="is_default" value="1"><label class="form-check-label" for="address-default">Make this my default address</label></div><button class="easy-btn" type="submit">Save address</button></form></div></div><div class="col-lg-7"><div class="row g-3"><?php if ($addresses === []): ?><div class="col-12"><div class="easy-card"><h2>No addresses yet</h2><p>Add at least two addresses when pickup and delivery are in different locations.</p></div></div><?php endif; ?><?php foreach ($addresses as $address): ?><div class="col-md-6"><article class="easy-card address-card"><div class="d-flex justify-content-between gap-3"><div class="card-icon"><i class="bi bi-geo-alt"></i></div><?php if ($address['is_default']): ?><span class="status-pill align-self-start">Default</span><?php endif; ?></div><h2><?= e($address['label']) ?></h2><p><strong><?= e($address['recipient_name']) ?></strong><br><?= e(AddressService::formatted($address)) ?><br><?= e($address['phone']) ?></p><?php if ($address['directions']): ?><small><?= e($address['directions']) ?></small><?php endif; ?></article></div><?php endforeach; ?></div></div></div></div></section>
